'use strict';
let workspacePrefs;try{workspacePrefs=JSON.parse(localStorage.getItem('royal-workspace-v2'))||{}}catch{workspacePrefs={}}
workspacePrefs={copilot:innerWidth>=1440,expanded:false,widgets:{pulse:true,deadlines:true,shipments:true,tools:true},...workspacePrefs};
let aiMessages=[],communicationDrafts={},copilotDraft='',aiTurnSequence=0;
const aiOrb=(small=false)=>`<span class="ai-orb ${small?'small':''}" aria-hidden="true"><img src="assets/royal-copilot-orb-${small?64:256}.webp" width="${small?32:112}" height="${small?32:112}" alt="" decoding="async"></span>`;
function saveWorkspace(){try{localStorage.setItem('royal-workspace-v2',JSON.stringify(workspacePrefs))}catch{}}
function workspaceShell(){const items=[['overview','grid'],['shipments','truck'],['deadlines','clock'],['documents','file'],['communications','chat']];return`<div class="shell studio ${view==='shipments'&&atlasView==='globe'?'atlas-workspace':''} ${workspacePrefs.copilot?'with-copilot':''} ${workspacePrefs.expanded?'rail-expanded':''}"><aside class="sidebar"><button class="rail-brand" data-nav="overview" aria-label="ROYAL · ops"><img class="official-mark" src="assets/royal-ops-mark.svg" alt=""><img class="official-wordmark" src="assets/royal-ops-logo.png" alt="ROYAL · ops"></button><button class="rail-toggle" data-workspace="rail" aria-expanded="${workspacePrefs.expanded}" aria-label="${workspacePrefs.expanded?tr('Collapse navigation','Contraer navegación'):tr('Expand navigation','Expandir navegación')}">${icon('chevron')}<span>${tr('Collapse menu','Contraer menú')}</span></button><nav class="nav" aria-label="${tr('Main navigation','Navegación principal')}">${items.map(([n,ic])=>`<button data-nav="${n}" class="${view===n?'active':''}" aria-label="${tr(...names[n])}" title="${tr(...names[n])}" ${view===n?'aria-current="page"':''}>${icon(ic)}<span class="rail-label">${tr(...names[n])}</span><span class="rail-short">${shortNavigationLabel(n)}</span>${n==='deadlines'&&activeDeadlines().some(d=>urgent(d)||!d.verified)?'<i class="rail-alert"></i>':''}<em>${tr(...names[n])}</em></button>`).join('')}<div class="rail-separator"></div><button data-workspace="copilot" class="${workspacePrefs.copilot?'copilot-active':''}" aria-label="${tr('Toggle Royal Copilot','Mostrar u ocultar Royal Copilot')}" title="Royal Copilot">${aiOrb(true)}<span>Royal Copilot</span><span class="rail-short">Copilot</span><em>Royal Copilot</em></button><button data-nav="automations" class="${view==='automations'?'active':''}" aria-label="${tr(...names.automations)}" title="${tr(...names.automations)}">${icon('bolt')}<span>${tr(...names.automations)}</span><span class="rail-short">${tr('Rules','Reglas')}</span><em>${tr(...names.automations)}</em></button><button class="mobile-settings" data-nav="settings" aria-label="${tr('Workspace settings','Ajustes del espacio de trabajo')}" title="${tr('Settings','Ajustes')}">${icon('settings')}</button><button class="mobile-more ${['documents','automations','settings'].includes(view)?'active':''}" data-responsive="more" aria-label="${tr('More navigation','Más opciones')}" aria-haspopup="dialog">${icon('more')}<span class="rail-short">${tr('More','Más')}</span></button></nav><div class="rail-bottom"><button class="rail-settings ${view==='settings'?'active':''}" data-nav="settings" aria-label="${tr('Workspace settings','Ajustes del espacio de trabajo')}" title="${tr('Workspace settings','Ajustes del espacio de trabajo')}">${icon('settings')}<span>${tr('Settings','Ajustes')}</span></button><button class="rail-profile" data-workspace="shift" aria-label="${tr('Your shift','Tu turno')}" title="Alex Rivera"><span class="avatar">AR</span><span>Alex Rivera<small>${tr('Operations lead','Líder de operaciones')}</small></span></button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><strong>${title()}</strong></div><div class="topactions"><form id="workspace-command-form" class="command-search">${icon('search')}<input id="workspace-command" aria-label="${tr('Search shipments or ask Copilot','Buscar embarques o preguntar a Copilot')}" placeholder="${tr('Search or ask Copilot…','Busca o pregunta a Copilot…')}" value="${esc(search)}" autocomplete="off"><kbd>⌘ K</kbd></form><button class="iconbtn lang" data-action="language" aria-label="${tr('Switch to Spanish','Cambiar a inglés')}">${state.lang==='en'?'ES':'EN'}</button><button class="iconbtn" data-action="theme" aria-label="${tr('Toggle light and dark theme','Cambiar tema claro y oscuro')}">${icon(state.theme==='light'?'moon':'sun')}</button><button class="iconbtn notification" data-nav="deadlines" aria-label="${tr('Open deadline alerts','Ver alertas de plazos')}">${icon('bell')}</button><button class="copilot-top" data-workspace="copilot" aria-label="${tr('Toggle Royal Copilot','Mostrar u ocultar Royal Copilot')}">${aiOrb(true)}<span>Copilot</span></button></div></header><div class="content">${page()}<footer class="footnote"><span><i class="dot green"></i>${tr('Presentation workspace · October 19, 2026 · Sample data','Espacio de presentación · 19 de octubre de 2026 · Datos demo')}</span><span>${tr('AI assistance & integrations simulated','Asistencia IA e integraciones simuladas')}</span></footer></div></main><div class="copilot-slot" id="royal-copilot-panel"><button class="copilot-backdrop" data-workspace="copilot" aria-label="${tr('Dismiss Copilot','Cerrar Copilot')}" tabindex="-1"></button>${copilotPanel()}</div></div>`}
function widgetHeader(h,sub,action=''){return`<div class="widget-header"><div><h2>${h}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function dashboardOverview(){const act=state.shipments.filter(s=>s.status!=='delivered'),freshCount=act.filter(s=>!stale(s)).length,pct=act.length?Math.round(freshCount/act.length*100):100,ds=activeDeadlines().filter(d=>urgent(d)||!d.verified),exposure=ds.reduce((a,d)=>a+d.rate,0),modes=[['Ocean','Marítimo','ship'],['Ground','Terrestre','truck'],['Air','Aéreo','plane']],openThreads=state.threads.length,w=workspacePrefs.widgets;return`<div class="studio-heading concise-heading"><div><h1>${tr('Control tower','Torre de control')}</h1><p class="page-context">${act.length} ${tr('active shipments','embarques activos')} · ${ds.length} ${tr('priority deadlines','plazos prioritarios')} · ${state.shipments.filter(stale).length} ${tr('status follow-ups','seguimientos de estado')}</p><small class="workspace-snapshot">${tr('Demo snapshot · Oct 19, 09:00 PDT','Datos demo · 19 oct, 09:00 PDT')}</small></div><div class="actions">${btn(tr('Customize','Personalizar'),'data-workspace="customize"','','settings')}${btn(tr('New shipment','Nuevo embarque'),'data-action="new-shipment"','primary','plus')}</div></div><div class="studio-kpis">${[[tr('Active shipments','Embarques activos'),act.length,'truck',tr('Ground, ocean & air','Terrestre, marítimo y aéreo'),''],[tr('Priority deadlines','Plazos prioritarios'),ds.length,'clock',tr('Verified cutoffs + dates to verify','Límites verificados + fechas por verificar'),'amber'],[tr('Daily exposure*','Exposición diaria*'),money(exposure),'shield',tr('Illustrative USD / container / day','USD ilustrativos / contenedor / día'),'red'],[tr('Status follow-ups','Seguimientos de estado'),state.shipments.filter(stale).length,'refresh',tr('No update in over 6 hours','Más de 6 horas sin novedades'),'']].map(([h,n,ic,sub,color])=>`<article class="mini-kpi"><div class="kpi-icon ${color}">${icon(ic)}</div><div><p>${h}</p><strong class="${color}">${n}</strong><small>${sub}</small></div></article>`).join('')}</div><div class="bento-grid">${w.pulse?`<section class="bento-card pulse-card"><div class="pulse-header"><span>${tr('Shipment pulse','Pulso de embarques')}</span>${badge(tr('Demo snapshot','Escenario demo'),'neutral')}</div><h2>${tr('Active shipments by mode','Embarques activos por modalidad')}</h2><p>${tr('Current distribution across ocean, ground and air.','Distribución actual entre marítimo, terrestre y aéreo.')}</p><div class="mode-bars">${modes.map(([en,es,ic])=>{const n=act.filter(s=>s.mode.startsWith(en)).length;return`<div><span>${icon(ic)}${tr(en,es)}</span><div><i style="width:${act.length?n/act.length*100:0}%"></i></div><b>${n}</b></div>`}).join('')}</div><div class="pulse-bottom"><span>${act.length} ${tr('active shipments','embarques activos')} · ${state.shipments.length} ${tr('total records','registros totales')}</span><button data-nav="shipments" aria-label="${tr('View shipments','Ver embarques')}">${icon('arrow')}</button></div><img class="pulse-artwork" src="assets/royal-connected-freight.svg" alt="" aria-hidden="true"></section><section class="bento-card freshness-card">${widgetHeader(tr('Status health','Salud del seguimiento'),tr('Active shipments with recent updates','Embarques activos con novedades recientes'))}<div class="fresh-gauge" style="--progress:${pct*1.8}deg"><div><strong>${pct}%</strong><span>${freshCount} ${tr('of','de')} ${act.length} ${tr('fresh','al día')}</span></div></div><p>${tr('Updated within the last 6 hours.','Actualizados en las últimas 6 horas.')}</p>${btn(tr('Review follow-ups','Revisar seguimientos'),'data-workspace="stale"','small','arrow')}</section>`:''}${w.deadlines?`<section class="bento-card deadline-widget">${widgetHeader(tr('Priority deadlines','Plazos prioritarios'),tr('Your priority queue · Terminal local time','Tu cola prioritaria · Hora local de terminal'),`<button class="widget-arrow" data-nav="deadlines" aria-label="${tr('All deadlines','Todos los plazos')}">${icon('arrow')}</button>`)}<div class="compact-deadlines">${ds.slice(0,3).map(d=>`<button class="deadline-item" data-deadline="${d.id}"><span class="deadline-symbol ${urgent(d)?'red':'amber'}">${icon(d.kind==='return'?'box':'clock')}</span><span><b>${d.container}</b><small>${kind(d)} · ${shipment(d.shipment).owner.split(' ')[0]}</small></span><span class="deadline-due"><b class="${urgent(d)?'red':'amber'}">${d.verified?`${hours(d)}h`:tr('Verify','Verificar')}</b><small>${d.verified?dueLabel(d):tr('Source not confirmed','Fuente sin confirmar')}</small></span></button>`).join('')||`<div class="empty">${icon('check')}${tr('No priority deadlines pending.','No hay plazos prioritarios pendientes.')}</div>`}</div><div class="widget-footer">${tr('*Illustrative flat rates; shared containers counted once.','*Tarifas planas ilustrativas; contenedores compartidos contados una vez.')}</div></section><section class="bento-card insight-widget">${widgetHeader(`${aiOrb(true)} ${tr('Copilot insights','Ideas de Copilot')}`,tr('Grounded in this workspace’s demo records','Basadas en los registros demo de este espacio'),badge(tr('Demo','Demo'),'neutral'))}<div class="insight-statement">${ds.length?tr('Priority deadlines to review','Plazos prioritarios por revisar'):tr('No priority deadlines','Sin plazos prioritarios')}</div><p>${ds.filter(d=>d.verified&&urgent(d)).length} ${tr('verified deadlines due in 24 hours.','plazos verificados vencen en 24 horas.')} ${activeDeadlines().filter(d=>!d.verified).length} ${tr('date(s) still need source verification.','fecha(s) necesitan verificar su fuente.')}</p><div class="insight-tags">${badge(tr('Source linked','Fuentes vinculadas'),'green')}${badge(tr('Review before acting','Revisar antes de actuar'),'neutral')}</div><button class="insight-ask" data-ai-intent="deadlines">${icon('spark')}${tr('Help me prioritize','Ayúdame a priorizar')}${icon('arrow')}</button></section>`:''}${w.shipments?`<section class="bento-card shipment-widget">${widgetHeader(tr('Shipment workspace','Espacio de embarques'),tr('Status, route and next checkpoint.','Estado, ruta y próximo control.'),link(tr('View all','Ver todos'),'data-nav="shipments"'))}${shipTabs()}${shipmentTable(4)}<div class="widget-footer">${tr('Showing','Mostrando')} ${Math.min(4,filteredShips().length)} ${tr('of','de')} ${filteredShips().length} · ${tr('Oct 19, 09:00 PDT snapshot','Escenario del 19 oct, 09:00 PDT')}</div></section>`:''}${w.tools?`<section class="bento-card tool-widget">${widgetHeader(tr('Documents','Documentos'),tr('Create drafts from shipment records.','Crear borradores con los datos del embarque.'),icon('file'))}<div class="tool-count"><strong>${state.docs.length}</strong><span>${tr('documents in this demo workspace','documentos en este espacio demo')}</span></div><div class="tool-actions">${btn(tr('Create BOL / delivery order','Crear BOL / orden de entrega'),'data-action="document"','primary small','plus')}<button class="mini-assist" data-ai-intent="documents" aria-label="${tr('Check document readiness','Revisar preparación documental')}" title="${tr('Check document readiness','Revisar preparación documental')}">${icon('spark')}</button></div></section><section class="bento-card tool-widget communication-widget">${widgetHeader(tr('Communications','Comunicación'),tr('Threads linked to shipments.','Conversaciones vinculadas a embarques.'),icon('chat'))}<div class="channel-dots"><span>${icon('whatsapp')}</span><span>${icon('mail')}</span><span>${icon('sms')}</span><span>${icon('phone')}</span><p><b>${openThreads}</b> ${tr('shipment-linked threads','conversaciones vinculadas')}</p></div><div class="tool-actions">${btn(tr('Open communication hub','Abrir centro de comunicación'),'data-nav="communications"','small','arrow')}${btn(tr('Draft follow-up','Redactar seguimiento'),'data-ai-intent="followup"','small','spark')}</div></section>`:''}</div>`}
function aiPrompt(intent){return({brief:tr('Give me my operations briefing','Dame mi resumen de operaciones'),deadlines:tr('Which deadlines should I prioritize?','¿Qué plazos debo priorizar?'),followup:tr('Draft a carrier follow-up','Redacta un seguimiento al transportista'),documents:tr('Check document readiness','Revisa la preparación documental'),status:tr('Which shipments need an update?','¿Qué embarques necesitan actualización?')})[intent]||intent}
function aiIsBusy(){return aiMessages.some(m=>m.pending)}
function aiThreadBody(){if(!aiMessages.length)return`<div class="copilot-welcome" data-ai-key="welcome">${aiOrb()}<h2>Royal Copilot</h2><p>${tr('Review deadlines, summarize shipments or draft follow-ups.','Revisa plazos, resume embarques o prepara seguimientos.')}</p><div class="ai-prompts">${[['brief','grid'],['deadlines','clock'],['followup','chat'],['documents','file']].map(([intent,ic])=>`<button data-ai-intent="${intent}">${icon(ic)}<span>${aiPrompt(intent)}</span>${icon('arrow')}</button>`).join('')}</div><div class="assistant-scope">${icon('shield')}<p>${tr('Demo assistance uses the sample records in this workspace. No external AI service is connected.','La asistencia demo usa los registros de ejemplo de este espacio. No hay un servicio de IA externo conectado.')}</p></div></div>`;
 return aiMessages.map(m=>`<section class="ai-turn" data-ai-key="turn-${m.sequence}" data-ai-state="${m.pending?'thinking':'ready'}"><div class="ai-user-message">${esc(m.question)}</div><div class="ai-answer"><div class="ai-answer-label">${aiOrb(true)}<b>Royal Copilot</b><span>Demo</span></div>${m.pending?`<div class="ai-thinking" role="status"><span class="ai-thinking-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>${tr('Reviewing demo records…','Revisando registros demo…')}</span></div>`:`<div class="ai-answer-content">${aiAnswer(m)}</div>`}</div></section>`).join('')+(aiIsBusy()?'':`<div class="ai-next-prompts" data-ai-key="prompts">${['brief','deadlines','followup','documents'].map(i=>`<button data-ai-intent="${i}">${aiPrompt(i)}</button>`).join('')}</div>`)}

function copilotPanel(){return`<aside class="copilot-panel" aria-label="Royal Copilot"><header class="copilot-header"><div>${aiOrb(true)}<span><b>Royal Copilot</b><small><i class="dot green"></i>${tr('Demo assistant · Workspace context','Asistente demo · Contexto del espacio')}</small></span></div><div><button data-workspace="clear-ai" class="ai-icon-button" aria-label="${tr('New assistant conversation','Nueva conversación con asistente')}" title="${tr('New conversation','Nueva conversación')}">${icon('refresh')}</button><button data-workspace="copilot" class="ai-icon-button" aria-label="${tr('Close Copilot','Cerrar Copilot')}">${icon('x')}</button></div></header><div class="ai-context-strip">${icon('box')}<span>${aiMessages.at(-1)?.shipment?esc(aiMessages.at(-1).shipment):tr('All operations','Todas las operaciones')}</span><span>${tr('Demo data','Datos demo')}</span></div><div class="copilot-messages" id="copilot-messages" aria-live="polite" aria-busy="${aiIsBusy()}">${aiThreadBody()}</div><div class="copilot-composer"><form id="copilot-form"><label class="sr-only" for="copilot-input">${tr('Ask Royal Copilot','Preguntar a Royal Copilot')}</label><textarea id="copilot-input" name="question" maxlength="1000" required rows="2" placeholder="${selectedShipment?tr('Ask about this shipment…','Pregunta por este embarque…'):tr('What needs my attention today?','¿Qué necesita mi atención hoy?')}"></textarea><button type="submit" ${aiIsBusy()?'disabled aria-busy="true"':''} aria-label="${tr('Ask Copilot','Preguntar a Copilot')}">${icon('arrow')}</button></form><p>${icon('shield')}${tr('Simulated assistance · Review before acting','Asistencia simulada · Revisa antes de actuar')}</p></div></aside>`}
function aiSource(id,label,deadline=false){return`<button class="ai-source" ${deadline?`data-deadline="${id}"`:`data-shipment="${id}"`}>${icon(deadline?'clock':'box')}${esc(label||id)}${icon('chevron')}</button>`}
function resolveIntent(q){const text=q.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');if(/dark|oscuro|light theme|tema claro/.test(text))return'theme';if(/draft|redact|message|mensaje|follow.up|seguimiento al|carrier|transportista/.test(text))return'followup';if(/document|bol\b|delivery order|orden de entrega|preparacion/.test(text))return'documents';if(/deadline|priorit|free day|lfd|plazo|dia libre|empty return|devolucion/.test(text))return'deadlines';if(/stale|update|actualiza|sin novedades|status/.test(text))return'status';if(/brief|resumen|attention|atencion|operation|operacion|today|hoy/.test(text))return'brief';return'unknown'}
async function runAssistant(question,intent){
 const q=String(question||'').trim().slice(0,1000);if(!q||aiIsBusy())return;
 const id=state.shipments.find(s=>q.toLowerCase().includes(s.id.toLowerCase())||q.toLowerCase().includes(s.container.toLowerCase()))?.id||selectedShipment;
 intent=intent||resolveIntent(q);if(id&&['status','unknown'].includes(intent))intent='shipment';
 const message={question:q,intent,shipment:id,sequence:++aiTurnSequence,pending:true};
 copilotDraft='';aiMessages.push(message);aiMessages=aiMessages.slice(-8);workspacePrefs.copilot=true;saveWorkspace();render({content:false});scrollAssistant();
 // A brief, explicit demo processing state; no external AI request is implied.
 await new Promise(resolve=>setTimeout(resolve,620));
 if(!aiMessages.includes(message))return;
 message.pending=false;render({content:false});scrollAssistant();
}
function scrollAssistant(){requestAnimationFrame(()=>{const m=$('#copilot-messages');if(m)m.scrollTo({top:m.scrollHeight,behavior:reduceWorkspaceMotion()?'instant':'smooth'});})}

function aiAnswer(m){const act=state.shipments.filter(s=>s.status!=='delivered'),focus=m.shipment&&shipment(m.shipment),needs=activeDeadlines().filter(d=>focus?d.container===focus.container:urgent(d)||!d.verified),late=state.shipments.filter(stale);switch(m.intent){case'brief':return`<p>${tr('Here is your current operations picture.','Este es el panorama actual de tu operación.')}</p><div class="ai-metrics"><div><b>${act.length}</b><span>${tr('active','activos')}</span></div><div><b>${needs.length}</b><span>${tr('priority dates','plazos clave')}</span></div><div><b>${late.length}</b><span>${tr('follow-ups','seguimientos')}</span></div></div>${aiModeChart(act)}<p>${tr('Start with confirmed cutoffs due in the next 24 hours, then verify unconfirmed dates and refresh stale statuses.','Comienza por límites confirmados que vencen en 24 horas; luego verifica fechas sin confirmar y actualiza estados atrasados.')}</p>${needs.slice(0,2).map(d=>aiSource(d.id,d.container,true)).join('')}<button class="ai-action" data-ai-intent="deadlines">${tr('Show my priority order','Ver mi orden de prioridades')}${icon('arrow')}</button><small class="ai-citation">${tr('Source: current shipment & deadline records · Fixed demo clock','Fuente: registros actuales de embarques y plazos · Reloj demo fijo')}</small>`;
case'deadlines':{const verified=needs.filter(d=>d.verified).sort((a,b)=>hours(a)-hours(b)),unverified=needs.filter(d=>!d.verified);return`<p>${tr('Protect verified cutoffs first. Keep unconfirmed dates in a separate verification queue.','Protege primero los límites verificados. Mantén las fechas sin confirmar en una cola de verificación separada.')}</p>${verified.map((d,i)=>`<div class="ai-priority"><div><b>${i+1}. ${kind(d)}</b>${badge(`${hours(d)}h`,urgent(d)?'red':'amber')}</div><p>${d.container}<br>${dueLabel(d)}<br>${esc(shipment(d.shipment).owner)}</p><small>${d.booked?tr('Booking recorded; completion evidence still needed.','Reserva registrada; aún se requiere evidencia de conclusión.'):tr('Confirm the plan with the carrier and record evidence when completed.','Confirma el plan con el transportista y registra evidencia al concluir.')}</small>${aiSource(d.id,tr('Review deadline source','Revisar fuente del plazo'),true)}</div>`).join('')||`<p>${tr('No verified priority deadlines are pending.','No hay plazos prioritarios verificados pendientes.')}</p>`}${unverified.map(d=>`<div class="ai-priority"><b class="amber">${tr('Verify the date','Verifica la fecha')} · ${d.container}</b><p>${tr('This cutoff is not confirmed. It cannot be treated as a reliable deadline.','Este límite no está confirmado. No debe tratarse como un plazo fiable.')}</p>${aiSource(d.id,tr('Open verification','Abrir verificación'),true)}</div>`).join('')}<small class="ai-citation">${tr('Source: container deadlines; terminal-local times. A booking does not resolve a deadline.','Fuente: plazos de contenedores; hora local de terminal. Una reserva no resuelve un plazo.')}</small>`}
case'status':return`<p>${late.length} ${tr('shipment(s) have no update within the demo’s six-hour window.','embarque(s) no tienen novedades en la ventana demo de seis horas.')}</p>${late.map(s=>`<div class="ai-priority"><b>${s.id}</b><p>${esc(s.carrier)} · ${esc(s.owner)}<br>${tr('Last update','Última actualización')}: ${s.updated.replace('T',' · ')}</p>${aiSource(s.id,tr('Review and update','Revisar y actualizar'))}</div>`).join('')||`<p>${tr('All active shipment statuses are fresh.','Todos los estados activos están al día.')}</p>`}<small class="ai-citation">${tr('Source: shipment update timestamps · Oct 19, 09:00 PDT','Fuente: fechas de actualización · 19 oct, 09:00 PDT')}</small>`;
case'shipment':if(!focus)return aiAnswer({...m,intent:'brief'});return`<h3>${focus.id}</h3><p>${esc(focus.origin)} → ${esc(focus.destination)}</p>${statusBadge(focus)}<p>${esc(focus.customer)} · ${esc(focus.carrier)}<br>ETA: ${focus.eta.replace('T',' · ')}<br>${tr('Owner','Responsable')}: ${esc(focus.owner)}</p><p>${tr('ETA is a forecast, not proof of arrival. Container deadlines are tracked independently.','La ETA es un pronóstico, no evidencia de llegada. Los plazos del contenedor se controlan por separado.')}</p>${aiSource(focus.id)}${activeDeadlines().filter(d=>d.container===focus.container).map(d=>aiSource(d.id,kind(d),true)).join('')}<button class="ai-action" data-ai-draft-for="${focus.id}">${tr('Prepare a follow-up draft','Preparar borrador de seguimiento')}${icon('arrow')}</button><small class="ai-citation">${tr('Source: current shipment record','Fuente: registro actual del embarque')}</small>`;
case'followup':{const s=focus||shipment(needs[0]?.shipment)||late[0]||state.shipments[0],d=activeDeadlines().find(d=>d.container===s.container),draft=carrierDraft(s,d);return`<p>${tr('Here is a draft for review. I have not sent it.','Este es un borrador para revisar. No lo he enviado.')}</p><div class="ai-draft"><span>${tr('CARRIER FOLLOW-UP','SEGUIMIENTO AL TRANSPORTISTA')}</span><p>${esc(draft)}</p></div>${aiSource(s.id)}<button class="ai-action" data-ai-use-draft="${s.id}">${tr('Review in communication hub','Revisar en centro de comunicación')}${icon('arrow')}</button><small class="ai-citation">${tr('Uses the carrier, shipment reference and verified cutoff if available. You choose whether to simulate sending.','Usa transportista, referencia y límite verificado si existe. Tú decides si simular el envío.')}</small>`}
case'documents':{const s=focus||state.shipments.find(s=>s.mode.startsWith('Ground'))||state.shipments[0],fields=[['shipper',tr('Shipper','Remitente')],['consignee',tr('Consignee','Consignatario')],['address',tr('Delivery address','Dirección de entrega')],['carrier',tr('Carrier','Transportista')],['container',tr('Equipment / container','Equipo / contenedor')],['cargo',tr('Cargo & quantity','Carga y cantidad')]],missing=fields.filter(([k])=>!s[k]||(k==='cargo'&&(!s.units||!s.weight)));return`<h3>${tr('Document readiness','Preparación documental')}</h3><p>${s.id}</p><div class="ai-checklist">${fields.map(([k,label])=>`<div class="${missing.some(x=>x[0]===k)?'amber':'green'}">${icon(missing.some(x=>x[0]===k)?'alert':'check')}<span>${label}</span></div>`).join('')}</div><p>${missing.length?tr('Complete missing fields before preparing the draft.','Completa los campos faltantes antes de preparar el borrador.'):tr('Core shipment fields are present. Review departure date, freight terms and document-specific requirements in the form.','Los campos base están completos. Revisa salida, flete y requisitos específicos en el formulario.')}</p>${aiSource(s.id)}<button class="ai-action" data-create-doc="${s.id}">${tr('Prepare BOL / delivery order','Preparar BOL / orden de entrega')}${icon('arrow')}</button><small class="ai-citation">${tr('Field checks only. Not a compliance or release authorization.','Solo validación de campos. No es autorización normativa ni de liberación.')}</small>`}
case'theme':return`<p>${tr('You can change the workspace appearance here.','Puedes cambiar la apariencia del espacio aquí.')}</p><button class="ai-action" data-action="theme">${icon(state.theme==='light'?'moon':'sun')}${tr('Switch workspace theme','Cambiar tema del espacio')}</button>`;
default:return`<p>${tr('I can demonstrate shipment summaries, deadline priorities, stale-status checks, document readiness and carrier follow-up drafts.','Puedo demostrar resúmenes de embarques, prioridades de plazos, seguimientos atrasados, preparación documental y borradores al transportista.')}</p><p>${tr('This prototype uses local rules rather than a connected language model, so I cannot reliably answer that request. Try a suggested question or include an existing shipment reference.','Este prototipo usa reglas locales en lugar de un modelo de lenguaje conectado, así que no puedo responder esa solicitud de forma fiable. Prueba una sugerencia o incluye una referencia existente.')}</p><button class="ai-action" data-ai-intent="brief">${tr('Show my briefing','Ver mi resumen')}${icon('arrow')}</button>`}}
function carrierDraft(s,d){return tr(`Hello ${s.carrier}, please confirm the current status and next milestone for ${s.id} (${s.container}). ${d?d.verified?`The ${d.kind==='lfd'?'last free day':'empty-return'} cutoff is ${dueLabel(d)}. Please confirm the appointment and completion evidence when available.`:'Please verify the terminal cutoff with an authoritative source before dispatch.':'Please confirm the latest ETA and any expected delays.'} Thank you.`,`Hola ${s.carrier}, confirma el estado actual y próximo hito de ${s.id} (${s.container}). ${d?d.verified?`El límite de ${d.kind==='lfd'?'último día libre':'devolución de vacío'} es ${dueLabel(d)}. Confirma la cita y evidencia de conclusión cuando esté disponible.`:'Verifica el límite de terminal con una fuente autorizada antes del despacho.':'Confirma la ETA más reciente y posibles retrasos.'} Gracias.`)}
function customizeWorkspace(){openOverlay(`${modalhead(tr('Dashboard settings','Ajustes del tablero'))}<div class="modalbody"><p class="muted" style="font-size:12px;line-height:1.8">${tr('Choose the cards you want in your overview. Your preferences stay in this browser.','Elige las tarjetas de tu resumen. Tus preferencias se guardan en este navegador.')}</p>${[['analytics',tr('Charts, workload & activity','Gráficos, carga y actividad')],['pulse',tr('Shipment pulse & status health','Pulso de embarques y salud del seguimiento')],['deadlines',tr('Priority deadlines & Copilot insights','Plazos prioritarios e ideas de Copilot')],['shipments',tr('Shipment workspace table','Tabla de embarques')],['tools',tr('Documents & communication tools','Herramientas documentales y de comunicación')]].map(([k,label])=>`<label class="widget-choice"><input type="checkbox" data-widget="${k}" ${workspacePrefs.widgets[k]!==false?'checked':''}>${label}</label>`).join('')}</div><div class="modalfoot">${btn(tr('Restore defaults','Restaurar valores'),'data-workspace="restore-widgets"')}${btn(tr('Done','Listo'),'data-close','primary','check')}</div>`,true)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.aiIntent){e.preventDefault();runAssistant(aiPrompt(b.dataset.aiIntent),b.dataset.aiIntent);return}if(b.dataset.aiDraftFor){e.preventDefault();runAssistant(tr(`Draft a follow-up for ${b.dataset.aiDraftFor}`,`Redacta seguimiento para ${b.dataset.aiDraftFor}`),'followup');return}if(b.dataset.aiUseDraft){e.preventDefault();const s=shipment(b.dataset.aiUseDraft),d=activeDeadlines().find(d=>d.container===s.container),draft=carrierDraft(s,d);contact(s.id).then(arrived=>{if(!arrived)return;const f=$('#message-form textarea');if(f){f.value=draft;communicationDrafts[selectedThread]=draft;f.focus()}toast(tr('Draft inserted for review. Nothing was sent.','Borrador insertado para revisar. No se envió nada.'));});return}switch(b.dataset.workspace){case'copilot':setCopilotOpen(!workspacePrefs.copilot);break;case'rail':workspacePrefs.expanded=!workspacePrefs.expanded;saveWorkspace();{const shell=document.querySelector('.studio.shell');shell?.classList.toggle('rail-expanded',workspacePrefs.expanded);const toggle=shell?.querySelector('.rail-toggle');if(toggle){toggle.setAttribute('aria-expanded',String(workspacePrefs.expanded));toggle.setAttribute('aria-label',workspacePrefs.expanded?tr('Collapse navigation','Contraer navegación'):tr('Expand navigation','Expandir navegación'))}}break;case'clear-ai':aiMessages=[];render({content:false});break;case'customize':customizeWorkspace();break;case'restore-widgets':workspacePrefs.widgets={analytics:true,pulse:true,deadlines:true,shipments:true,tools:true};saveWorkspace();render();customizeWorkspace();break;case'stale':shipFilter='attention';search='';go('shipments');break;case'shift':openOverlay(`${modalhead(tr('Shift summary','Resumen del turno'))}<div class="modalbody"><h3>Alex Rivera</h3><p class="muted">${tr('Operations lead · El Paso · Demo role','Líder de operaciones · El Paso · Rol demo')}</p><p>${state.shipments.filter(s=>s.owner==='Alex Rivera'&&s.status!=='delivered').length} ${tr('active shipments assigned to you.','embarques activos asignados a ti.')}</p>${btn(tr('Prepare my briefing','Preparar mi resumen'),'data-ai-intent="brief"','primary','spark')}</div><div class="modalfoot">${btn(tr('Close','Cerrar'),'data-close')}</div>`,true);break}});
document.addEventListener('change',e=>{if(e.target.dataset.widget){workspacePrefs.widgets[e.target.dataset.widget]=e.target.checked;saveWorkspace();render()}});
document.addEventListener('submit',e=>{if(!['copilot-form','workspace-command-form'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();if(e.target.id==='copilot-form'){const q=$('#copilot-input').value;runAssistant(q);return}const q=$('#workspace-command').value.trim();if(!q)return;if(resolveIntent(q)!=='unknown'||/\?|\b(summar|resume|explain|explica|help|ayuda)/i.test(q))runAssistant(q);else{search=q;shipFilter='all';go('shipments')}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#workspace-command')?.focus()}if(e.target.id==='copilot-input'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();runAssistant(e.target.value)}});

document.addEventListener('click',e=>{const b=e.target.closest('button[data-ai-summarize]');if(b){const id=b.dataset.aiSummarize;closeOverlay();runAssistant(tr(`Summarize shipment ${id}`,`Resume el embarque ${id}`),'shipment')}});

document.addEventListener('input',e=>{if(e.target.id==='copilot-input')copilotDraft=e.target.value;if(e.target.matches('#message-form textarea'))communicationDrafts[selectedThread]=e.target.value});

function aiModeChart(records){return `<div class="ai-result-chart" role="img" aria-label="${tr('Active shipments by mode','Embarques activos por modalidad')}"><b>${tr('Active shipments by mode','Embarques activos por modalidad')}</b>${[['Ocean','Marítimo'],['Ground','Terrestre'],['Air','Aéreo']].map(([en,es])=>{const n=records.filter(s=>s.mode.startsWith(en)).length;return `<div><span>${tr(en,es)}</span><i><em style="width:${records.length?n/records.length*100:0}%"></em></i><strong>${n}</strong></div>`}).join('')}</div><button class="ai-action" data-nav="overview">${tr('Show on dashboard','Ver en el dashboard')}${icon('arrow')}</button>`}

// Brief tactile feedback, without moving page geometry or restarting navigation fades.
document.addEventListener('pointerdown',event=>{
 const control=event.target.closest('.studio button:not(:disabled),#overlay .btn:not(:disabled)');
 if(!control||reduceWorkspaceMotion()||event.button!==0||!control.animate)return;
 if(control.closest('.atlas-stage,.tabs,.atlas-mode-tabs,.atlas-view-switch')||control.matches('.rail-toggle'))return;
 control.animate([{opacity:.72},{opacity:1}],{duration:240,easing:'cubic-bezier(.2,.7,.2,1)'});
});
